pub fn guarde(fila: &mut Vec<i32>, n: i32) {
    fila.push(n);
}

testsCode:
use desafio::guarde;

#[test]
fn testa_o_guarde_no_fim_da_fila() {
    let mut fila = vec![2, 4];
    guarde(&mut fila, 6);
    assert_eq!(fila[2], 6);
}

#[test]
fn testa_a_fila_cresceu_duas_vezes() {
    let mut fila = vec![2];
    guarde(&mut fila, 4);
    guarde(&mut fila, 6);
    assert_eq!(fila.len(), 3);
    assert_eq!(fila[0], 2);
}
